  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking whose end falls inside an active booking', async () => {
    await book(24, 25);
    const response = await book(23.5, 24.5, 'Overlap from the left');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects moving a booking on top of another one via PATCH', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Retro');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('returns the whole window when the room has no bookings', async () => {
    const from = inHours(10);
    const to = inHours(11);
    const response = await app.inject({
      method: 'GET',
      url: `/bookings/availability?roomId=${roomId}&from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}&duration=15`,
    });
    expect(response.statusCode).toBe(200);
    expect(response.json().slots).toEqual([{ startsAt: from, endsAt: to }]);
  });

  it('lists free slots around an existing booking', async () => {
    const created = await book(24, 25);
    const from = inHours(20);
    const to = inHours(30);
    const response = await app.inject({
      method: 'GET',
      url: `/bookings/availability?roomId=${roomId}&from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}&duration=30`,
    });
    const { slots } = response.json();
    expect(slots).toHaveLength(2);
    expect(slots[0]).toEqual({ startsAt: from, endsAt: created.json().startsAt });
    expect(slots[1]).toEqual({ startsAt: created.json().endsAt, endsAt: to });
  });

  it('excludes gaps shorter than the requested duration', async () => {
    await book(24, 24.25);
    const response = await app.inject({
      method: 'GET',
      url: `/bookings/availability?roomId=${roomId}&from=${encodeURIComponent(inHours(24))}&to=${encodeURIComponent(inHours(24.5))}&duration=30`,
    });
    expect(response.json().slots).toHaveLength(0);
  });

  it('rejects an availability window where "from" is not before "to"', async () => {
    const response = await app.inject({
      method: 'GET',
      url: `/bookings/availability?roomId=${roomId}&from=${encodeURIComponent(inHours(10))}&to=${encodeURIComponent(inHours(5))}&duration=15`,
    });
    expect(response.statusCode).toBe(400);
  });

  it('creates every booking in a batch when none conflict', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings/batch',
      payload: {
        bookings: [
          { roomId, userId, title: 'One', startsAt: inHours(40), endsAt: inHours(41) },
          { roomId, userId, title: 'Two', startsAt: inHours(41), endsAt: inHours(42) },
        ],
      },
    });
    expect(response.statusCode).toBe(201);
    expect(response.json().data).toHaveLength(2);
  });

  it('rejects the whole batch when an item conflicts with an existing booking', async () => {
    await book(24, 25);
    const response = await app.inject({
      method: 'POST',
      url: '/bookings/batch',
      payload: {
        bookings: [
          { roomId, userId, title: 'Free', startsAt: inHours(50), endsAt: inHours(51) },
          { roomId, userId, title: 'Clash', startsAt: inHours(24.5), endsAt: inHours(25.5) },
        ],
      },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_BATCH_CONFLICT');
    expect(response.json().error.details.conflicts).toEqual([
      { index: 1, conflictingBookingId: expect.any(String) },
    ]);

    const list = await app.inject({ method: 'GET', url: '/bookings' });
    expect(list.json().pagination.total).toBe(1);
  });

  it('rejects the whole batch when two of its items conflict with each other', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings/batch',
      payload: {
        bookings: [
          { roomId, userId, title: 'A', startsAt: inHours(60), endsAt: inHours(61) },
          { roomId, userId, title: 'B', startsAt: inHours(60.5), endsAt: inHours(61.5) },
        ],
      },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.details.conflicts).toEqual([{ index: 1, conflictingBatchIndex: 0 }]);

    const list = await app.inject({ method: 'GET', url: '/bookings' });
    expect(list.json().pagination.total).toBe(0);
  });
});

