    expect(response.json().error.details.conflicts).toEqual([{ index: 1, conflictingBatchIndex: 0 }]);

    const list = await app.inject({ method: 'GET', url: '/bookings' });
    expect(list.json().pagination.total).toBe(0);
  });
});

